from lib import *
S = SS('n15')
steps = [
    step("RemoveExtraSlash 默认 false:/users//42、//users/42、/a//b、/a/./b、/a/x/../b 都是 404。设成 true 后:/users//42 与 //users/42 命中 id=42;/a//b、/a/./b、/a/x/../b 都命中 /a/b;/f/x//y 的 *p 从 \"/x//y\" 变成 \"/x/y\"。注意 /users/42//(结尾两个斜杠)没有直接命中,而是 301 到 /users/42/,再 301 到 /users/42,共两跳。", t=tl(S(1)), mark=lidx(S(1), '/users//42     → 200', '/a/x/../b      → 200', '/f/x//y        → 200 "p=\\"/x/y\\""', '/users/42//    → 301'), done=lidx(S(1), '/users/42      → 200', '/users//42     → 404'), b=bars([['关闭时命中', 2, '2 / 9'], ['打开时命中', 7, '7 / 9']], 9, mark=[1], done=[0]), kv=KV([['// ./ ..', '直接命中,不重定向'], ['/users/42//', '两跳 301'], ['*p 的值', '多余斜杠被去掉']], ['// ./ ..'])),
    step("匹配用的是清理后的路径,c.Request.URL.Path 保持原样:/f/a//b 与 /f//a/b 的 p 都是 \"/a/b\"(URL.Path 仍是原来的);/f/a/../b 的 p 是 \"/b\"——cleanPath 还会解析 .. 和 ./,所以通配符的值被改写了;/f/a/./b/ 的 p 是 \"/a/b/\",结尾斜杠保留。", t=tl(S(2)), mark=lidx(S(2), '/f/a/../b', '/f/a//b'), done=lidx(S(2), '/f//a/b', '/f/a/./b/'), kv=KV([['匹配用', '清理后的路径'], ['URL.Path', '仍是原始路径'], ['*p', '值已被清理,.. 被解析掉']], ['*p'])),
    step("与重定向的组合(RemoveExtraSlash / RedirectFixedPath):都关:/users//42 404,/dir 301→/dir/,//dir/ 404,/dir// 301→/dir/;只开 RemoveExtraSlash:/users//42 200,//dir/ 与 /dir// 都 200;只开 RedirectFixedPath:/users//42 301→/users/42,//dir/ 301→/dir/;两个都开:/users//42、//dir/、/dir// 都是直接 200。RemoveExtraSlash 让请求就地命中,RedirectFixedPath 让客户端多跑一趟。", t=tl(S(3)), mark=lidx(S(3), 'RemoveExtraSlash=true  RedirectFixedPath=true', 'RemoveExtraSlash=true  RedirectFixedPath=false'), done=lidx(S(3), 'RemoveExtraSlash=false RedirectFixedPath=false', 'RemoveExtraSlash=false RedirectFixedPath=true'), kv=KV([['RemoveExtraSlash', '就地命中,200'], ['RedirectFixedPath', '301 / 307 到规范路径'], ['都开', 'RemoveExtraSlash 先生效,直接 200']], ['RemoveExtraSlash'])),
    step("cleanPath 的规则(源码注释):重复斜杠合并成一个;删除 . 段;删除内部的 .. 及它前面的一段;根上的 /.. 变成 /。代价:/users/42 这样本来就规整的路径 0 次分配(开关打开前后一样);带 // 的 /users//42 打开后每个请求多 1 次分配(0 → 1)。", t=tl(S(4)), mark=lidx(S(4), 'RemoveExtraSlash=true  /users//42   1 allocs/请求'), done=lidx(S(4), 'Replace multiple slashes', 'Eliminate each . path name element', 'RemoveExtraSlash=true  /users/42    0 allocs/请求', 'RemoveExtraSlash=false /users//42   0 allocs/请求'), b=bars([['打开,/users/42', 0, '0 次分配'], ['打开,/users//42', 1, '1 次分配']], 1, done=[0], mark=[1]), kv=KV([['规整的路径', '0 次分配'], ['带 // 的路径', '多 1 次分配'], ['清理规则', '合并 //,去掉 .,解析 ..']], ['带 // 的路径'])),
]
A = mkartn('n15', 15, 'Gin,RemoveExtraSlash,cleanPath,路径清理,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 RemoveExtraSlash(默认 false):打开后 //、./、.. 的路径就地命中,不重定向;匹配用清理后的路径,URL.Path 保持原样,通配符的值也被清理;与 RedirectFixedPath 的组合;清理多余斜杠的请求多 1 次内存分配。',
    '客户端拼出了 /users//42 这样带双斜杠的 URL,Gin 默认给 404。RemoveExtraSlash 能让它直接命中,但它不只处理双斜杠。这篇列出打开前后的差别、*path 的值被怎样改写、和 RedirectFixedPath 的区别,以及代价。',
    [('404 → 200', 'RemoveExtraSlash 打开后 /users//42 的状态码'), ('"/b"', '打开后 /f/a/../b 的 *p 值——.. 被解析掉了'), ('0 → 1 次', '带 // 的请求每次多出的内存分配,规整的路径不分配')],
    [('就地命中', '<p>打开 <code>RemoveExtraSlash</code> 之后,<code>/users//42</code>、<code>//users/42</code>、<code>/a/./b</code>、<code>/a/x/../b</code> 都直接命中,响应码是 200,不会有重定向。只有结尾斜杠的规则没变:<code>/users/42//</code> 仍然要先 301 到 <code>/users/42/</code> 再 301 到 <code>/users/42</code>。</p>'),
     ('被清理的是匹配用的路径', '<p><code>c.Request.URL.Path</code> 保持请求里的原样,但 <code>c.Param</code> 取到的值来自清理后的路径:<code>*p</code> 里的 <code>//</code> 被合并,<code>..</code> 与 <code>.</code> 被解析掉(<code>/f/a/../b</code> 的 p 是 <code>/b</code>)。如果业务依赖 <code>*p</code> 里的原始字节(比如对象存储的 key 里允许双斜杠),就不能打开这个开关。</p>'),
     ('与 RedirectFixedPath 的区别', '<p>两个开关都能“修好”双斜杠,方式不同:<code>RemoveExtraSlash</code> 直接在服务端用清理后的路径匹配,客户端看不到变化;<code>RedirectFixedPath</code> 让客户端 301/307 到规范路径(还能修正大小写)。两个都开时,前者先生效,请求直接 200。</p>'),
     ('规则与代价', '<p>清理规则与标准库 <code>path.Clean</code> 相同:合并重复斜杠、删除 <code>.</code>、解析 <code>..</code>、根上的 <code>/..</code> 变成 <code>/</code>。规整的路径不需要分配;带 <code>//</code> 的路径每次请求多 1 次内存分配。</p>')],
    steps,
    [ENV_N_GIN + '。请求用 httptest 直接调用 ServeHTTP;分配次数用 testing.AllocsPerRun(2000 次平均);每种情形各一次',
     '没有验证:耗时(只统计了分配次数,没有测纳秒);与 UseRawPath、UseEscapedPath 同时打开时的交互;包含 %2F 的路径在 cleanPath 前后的行为;Group 前缀里带多余斜杠的路由(那是注册时的 path.Join 处理的,不受这个开关影响,见 Group 一篇)'],
    'RemoveExtraSlash')
